import { games, type Game } from "./game";

const englishStories: Record<number, string> = {
  1: "A conversation can end a fight, and a single decision can change a companion's fate. Create your own character for a fantasy adventure where turn-based battles test your ingenuity and difficult choices reveal who you want to be.",
  2: "Take up Geralt's swords and follow Ciri's trail across a land scarred by war. Between monster hunts and unexpected encounters, discover that the hardest choices rarely come down to simple right and wrong.",
  3: "A distant mountain, a cave that draws you off the road, a dragon overhead: in Skyrim, curiosity sets your course. Build your character around blades, magic or stealth, and make your own adventure in this rugged northern land.",
  4: "Leon's rescue mission becomes a fight for survival amid hostile stares and shrinking escape routes. Make every bullet count, read your surroundings and keep your nerve through encounters where horror and action collide.",
  5: "On Mexico's open roads, chase your next race or simply enjoy the scenery. Fill your garage with dream cars, make them your own and join a driving festival that stretches far beyond the asphalt.",
  6: "Holding an angle, timing an ability and creating space for a teammate can decide a round. Combine precise aim with your agent's toolkit, and turn each individual move into part of your team's plan.",
  7: "As Arthur Morgan, search for a place for your gang in a changing America and confront the cost of loyalty. Long rides, camp conversations and chance encounters make this Western's quiet moments as memorable as its daring robberies.",
  8: "Make your way through Night City as V, choosing whom to trust as technology reshapes your capabilities. Build a style around combat, stealth and cybernetic tools to face the dangers beneath the city's neon glow.",
  9: "A secret behind a ruin or a castle on the horizon is enough to pull you off the beaten path in Elden Ring. Shape your fighting style, learn from defeat and gradually unravel enemies that once seemed impossible to overcome.",
  10: "Journey with Kratos and Atreus through the dangerous realms of Norse myth, where the road tests and reshapes a father-son bond. Weighty axe combat, exploration and puzzles give this deeply personal adventure its rhythm.",
  11: "Cross a post-pandemic America with Joel and Ellie, where every safe corner offers only a brief respite. Scarce supplies shape the struggle to survive, but the heart of the journey is a bond slowly forged in danger.",
  12: "Lose yourself in Hogwarts' corridors, learn new spells and explore the magical world beyond the school. From lessons to hidden passages, student life opens into an adventure filled with ancient secrets and dangerous encounters.",
  13: "Travel through ancient Greece as a mercenary, following traces of your family from island shores to battlefields. Sea voyages, exploration and personal choices give you room to shape an odyssey of your own against a historical backdrop.",
  14: "Defend Tsushima as Jin Sakai, finding a path between samurai tradition and the brutal realities of invasion. Wind-guided exploration, sword duels and silent attacks offer different ways to fight for the island's future.",
  15: "Step into the intersecting lives of three criminals in Los Santos, where grand schemes collide with everyday chaos. Between tense heists and the freedom to roam the city, trouble always seems to be waiting around another corner.",
  16: "Race for money by day in Palm City, then head out at night to build your reputation under police pressure. The car you shape in your garage becomes your partner through tight corners and escapes that test your appetite for risk.",
  17: "Taking a corner too fast can become an experiment of its own in BeamNG.drive. Explore how vehicles respond to different roads and conditions; sometimes the most interesting outcome is the one your original driving plan never intended.",
  18: "Find the fault under the hood, strip out worn parts and get a tired car ready for the road again. Car Mechanic Simulator 2021 trades the rush of racing for the satisfaction of solving one workshop job at a time.",
  19: "Modern Warfare puts you amid modern conflict, keeping your attention fixed on what might wait around the next corner. From cinematic campaign missions to multiplayer battles, positioning matters alongside your aim.",
  20: "Winning a round sometimes starts with a smart purchase long before the first shot. Combine map knowledge, plans around bomb sites and clear communication in Counter-Strike 2, turning small advantages into decisive moments.",
  21: "Your Legend's abilities shape how your squad enters a fight and how it escapes one in Apex Legends. Move quickly, share resources and find a rhythm with your teammates as the battlefield closes in.",
  22: "Inside an asylum with only a camera, seeing into the darkness can be easier than escaping what it reveals. Outlast asks you to hide and search for a way through, buying precious seconds from threats you cannot simply fight.",
  23: "You awaken without your memory in a castle where every clue to the past brings fresh unease. As you work through its puzzles, Amnesia: The Dark Descent surrounds you with a creeping horror built on darkness and helplessness.",
  24: "Enter a haunted location with your team, set up your equipment and identify its unseen resident through evidence. In Phasmophobia, a routine reading can turn into a desperate scramble for cover when a hunt begins.",
  25: "Growing a small settlement means constantly balancing your economy against the needs of your army. Manage resources, advance through the ages and use your civilization's strengths to bring your battlefield plans to life in Age of Empires IV.",
  26: "From the founding of your first city, every turn gives your civilization a new direction. Chart a course through science, culture, diplomacy and war in Civilization VI, and watch a long-term plan reshape the world.",
  27: "The grand plan you build on the campaign map faces its real test among vast armies and fantastical creatures. Total War: Warhammer III combines empire management with real-time battles, asking you to earn victory both on and off the field.",
  28: "A shelter made from a handful of blocks can grow into the world you have always wanted to build. In Minecraft, you choose the goal: delve into the mines, survive the wilderness or simply create.",
  29: "Bring an overgrown farm into shape, filling your days with crops, visits to town and small discoveries. Progress in Stardew Valley is measured not just in earnings, but in the relationships you build and the pace of life you choose.",
  30: "As Zagreus, fight to escape the Underworld with a different mix of powers and encounters on each attempt. Defeat in Hades is more than a trip back: it brings new conversations, growth and possibilities that invite another run.",
  31: "Search Teyvat for your missing sibling, letting distant peaks and roadside puzzles draw you into adventures along the way. Build a party of different characters, combine their elements and uncover the secrets of this colourful world.",
  32: "Where you land, what you loot and when you choose to fight shape your chances of survival in PUBG Mobile. As the safe zone shrinks, the smartest move may be to fire, or to reach a better position without being seen.",
  33: "Call of Duty Mobile brings together intense firefights for a short break and longer battle royale contests. Shape your loadout, learn how the maps flow and turn quick decisions into an advantage for your team.",
  34: "In Brawl Stars, quick decisions in a compact arena can turn a match around in seconds. Learn each brawler's abilities, create openings with teammates and stay focused on the objective through short, lively contests.",
  35: "In Clash Royale, when and where you play your cards matters as much as the cards themselves. Spend elixir carefully, read your opponent and turn a small opening on defence into a counterattack against their towers.",
  36: "Tasks are getting done, but someone's story may not quite add up. Piece together clues as a crewmate or earn trust as an impostor in Among Us, where a single sentence in a meeting can shift everyone's suspicions.",
  37: "Every run in Dead Cells is a chance to learn a new fighting style with the weapons you discover. Read enemy rhythms, weigh your risks and return better prepared after defeat in a game built around fluid, demanding combat.",
  38: "A journey that begins with a simple pickaxe in Terraria can grow into underground expeditions, ambitious builds and demanding boss battles. Every material hints at something new to craft, and every tunnel may lead to an unexpected discovery.",
  39: "Roblox is a gateway to player-created experiences rather than a single adventure. Tackle an obstacle course with friends, role-play or step into a completely different world; what you find depends on the experience you choose.",
  40: "Asphalt 9: Legends chases speed and spectacular racing moments rather than strict driving realism. Throw licensed cars into corners, time your nitro and keep up the pace on tracks punctuated by ramps and jumps.",
  41: "The open roads of CarX Street become a testing ground for the changes you make in your garage. Upgrade your car, enter street races and get to know your machine a little better with every corner.",
  42: "In Pokemon Unite, knowing when to carry your points to a goal zone matters as much as defeating opponents. Combine your Pokémon's abilities with your team's plans, balancing map objectives against opportunities to score.",
  43: "A path that looks impossible can open up with a shift in perspective in Monument Valley. Turn and reshape its quiet architectural spaces on a journey that makes puzzle-solving feel like calm, visual discovery.",
  44: "A small lane advantage can become a major opening with timely team support in Mobile Legends: Bang Bang. Learn your hero's role, watch the map and focus on turning individual plays into a victory for the whole team.",
  45: "Turn a squad of favourite players into a team that works on the pitch in eFootball Mobile. Develop your players, create passing options and test your approach to football against different opponents online.",
  46: "As Commander Shepard, gather allies from different worlds and make difficult decisions in the face of a galactic threat. Across three games, Mass Effect Legendary Edition makes your relationships with crewmates as much a part of the journey as its battles.",
  47: "Searching for your missing son leads you through a ruined Boston shaped by competing communities and interests. Explore its remains, improve your equipment and carve out a place in Fallout 4's fractured world through the settlements you build.",
  48: "School life and friendships share a calendar with the Phantom Thieves' secret activities in Persona 5 Royal. Choose how to spend your time while venturing into the worlds of distorted hearts for turn-based battles, finding a balance between two lives.",
  49: "See medieval Bohemia through Henry's eyes on a journey where war, politics and personal stakes intertwine. Kingdom Come: Deliverance II asks for patience and considered choices, whether you are wielding a sword or talking your way through a problem.",
  50: "As a detective without his memory, you investigate not only a murder but also the person you have become. In Disco Elysium, voices within your mind interrupt conversations, while your words, flaws and choices shape the investigation.",
  51: "Swinging between New York's skyscrapers turns even a simple journey into a small spectacle. As Peter Parker, you fight crime on the streets while trying to hold together the life waiting outside the mask. Acrobatic combat and discoveries around the city bring the thrill of being a hero together with the weight of personal responsibility.",
  52: "Nathan Drake's plans for a quieter life unravel when his brother Sam returns with a trail leading to lost pirate treasure. Climb ancient structures, solve puzzles and follow a dangerous pursuit across distant corners of the world. Conversations between the brothers give the spectacular action a personal stake that reaches well beyond the promise of gold.",
  53: "The Federal Bureau of Control hides unsettling phenomena behind its ordinary office corridors when Jesse Faden arrives. Hurl objects with your mind, explore shifting spaces and piece together the institution's secrets through documents and strange encounters. Control pairs an atmosphere where every answer invites another question with energetic combat that turns the surroundings into weapons.",
  54: "Defeating a demon is only the beginning in Devil May Cry 5; the real pleasure lies in how creatively you do it. Move between Dante, Nero and V's distinct approaches, extending combos, learning attack rhythms and experimenting with stylish moves. Each encounter becomes a stage for developing your own fighting style as much as your reflexes.",
  55: "An orc you meet in Mordor can return as a personal rival who remembers your history. As Talion, challenge fortresses, uncover your opponents' weaknesses and build an army to shift the balance of power. The Nemesis system turns victories, escapes and unexpected confrontations into smaller stories that feel like your own within the wider war.",
  56: "A closed door in Rainbow Six Siege is more than an entrance: it may conceal a trap, a waiting opponent or the centre of your team's plan. Use your operator's equipment to gather information, prepare a defence or dismantle one. In fights where walls and sightlines can change, a timely call to your teammates can matter as much as a precise shot.",
  57: "The route to an objective changes dramatically with your choice of hero in Overwatch 2. Create space on the front line, keep your teammates standing or look for a gap in the enemy defence. Beneath the colourful battles is a contest of combining abilities at the right moment and adapting when your team's needs change.",
  58: "From your first landing to the final safe zone, Fortnite asks you to build a plan around whatever you find. Search for weapons and supplies while weighing when to engage and when to move. In building modes you can create your own cover, while no-build options put greater emphasis on making the most of the terrain around you.",
  59: "DOOM Eternal builds a combat rhythm that pushes you forward instead of letting you wait safely in a corner. As the Doom Slayer, switch weapons, target weaknesses and recover the resources you need from the fight itself. Every arena tests your speed and aggression alongside your ability to decide which threat deserves your attention first.",
  60: "Battlefield 1 explores different fronts of the First World War through personal war stories and large-scale battles. One moment takes you between trenches; another asks you to hold a line reshaped by vehicles and explosions. Supporting teammates and moving together can make a greater difference in its intense battlefields than trying to stand out alone.",
  61: "Engineer Isaac Clarke's mission to a silent spaceship becomes a survival nightmare haunted by sounds in narrow corridors. Facing Necromorphs takes more than firing blindly: you must think about where you aim and what resources remain. Dead Space keeps the urge to uncover the ship's fate in constant tension with the fear of opening its next door.",
  62: "As Amanda Ripley, move through a space station where you can never comfortably assume where your hunter is. Search for hiding places, consider distractions and sometimes make progress simply by waiting for the right moment. Crossing a corridor unharmed can feel like a major victory in Alien: Isolation, where feeling safe is no guarantee that you are.",
  63: "As Mono, travel alongside Six through a distorted world made even more unsettling by a child's perspective. Read the environment to solve puzzles, hide and escape at the right moment among oversized spaces and their threatening inhabitants. Little Nightmares II tells its disturbing tale through images, sounds and small details rather than lengthy explanations.",
  64: "Inside a research facility deep beneath the ocean, understanding your surroundings also means questioning what it is to be human. Records and encounters along SOMA's corridors raise difficult questions about consciousness and identity. Its horror comes not only from threats in the dark, but also from being left alone with what you have learned.",
  65: "James Sunderland travels to the fog-covered town of Silent Hill after receiving a letter apparently sent by his late wife. Search its empty streets and enclosed spaces, confronting puzzles, disturbing encounters and traces of the past. Silent Hill 2 draws its tension not just from enemies, but from the unease of trying to understand what everything means.",
  66: "In Crusader Kings III, you govern more than a country: you guide a dynasty shaped by ambitions and weaknesses. Marriages, succession, alliances and secret schemes can have consequences more powerful than an army. As one ruler's carefully built order passes to the next generation, you shape a family story as much as the borders on a map.",
  67: "A city that begins with a small road connection develops needs and problems of its own as new neighbourhoods grow. In Cities: Skylines, traffic, public transport, budgets and services form an interconnected system. Making a plan that looks good from above also work in everyday life is the real satisfaction of building your own metropolis.",
  68: "Success in Football Manager begins long before the decisions you make from the touchline on match day. Manage the transfer budget, plan training, develop young talent and build an approach that suits your squad. Injuries, expectations and opponents test those plans across a long season, making a decisive contribution from a player you developed feel especially personal.",
  69: "Lead the resistance against Earth's alien occupiers, risking your soldiers' lives with every mission. Cover, sightlines and turn order in XCOM 2 can turn a small operation into a major victory or a costly loss. Research at your base feeds into decisions in the field, while soldiers gradually become teammates you are reluctant to lose rather than names on a roster.",
  70: "Providing shelter for a few colonists in RimWorld soon becomes a balancing act of food, health, security and relationships. Personalities and needs shape daily life just as much as practical skills. Your responses to unexpected events may not produce a perfect plan, but they can create a messy, deeply personal survival story worth retelling.",
  71: "The pleasure of Euro Truck Simulator 2 lies as much in settling into the rhythm of a long journey as in delivering its cargo. Drive European roads, negotiate junctions and tight delivery spaces, and use your earnings to grow the business. New trucks and an expanding company offer progress, while the steady view through the windscreen leaves room to play without rushing.",
  72: "In The Sims 4, begin with a face, a home and a few personality traits, then shape the everyday life that grows from them. Career goals, friendships and small domestic problems keep pulling your plans in new directions. Aim for an ideal life or follow the unexpected stories that emerge as your characters interact with the world you have made.",
  73: "Revealing the true colour beneath a layer of dirt makes progress wonderfully visible in PowerWash Simulator. Clean vehicles, houses and varied locations with pressurised water, breaking large spaces into small, manageable tasks. Disappearing stains and the order you leave behind offer a quiet satisfaction built around your own pace rather than intense competition.",
  74: "Cody and May's transformation into dolls begins an unusual journey through the problems in their relationship. As chapters change in It Takes Two, so do the tools you use and the tasks you must accomplish together. Puzzles and lively action sequences make one player's opening the other's opportunity, placing genuine cooperation at the centre of the adventure.",
  75: "Opening two portals in Portal 2 changes how you see the geometry of an entire room. Connect momentum, switches and surrounding machinery while sharp humour cuts through the test chambers' sterile atmosphere. Alongside the single-player story, a separate cooperative adventure makes clear that the solution can depend as much on communication with your partner as on your own insight.",
  76: "Battlefield 5 turns Second World War fronts into broad clashes where infantry and vehicles converge on shared objectives. Reviving a teammate, supporting an advance or closing a gap in the defence can influence the course of a battle. The pressure shifting around you rewards being in the right place with your squad as much as accurate shooting.",
  77: "Entering Tarkov means thinking not only about the equipment you take in, but also about what you might bring back. Search for supplies during dangerous raids, listen carefully and weigh whether another fight is worth the potential gain. Reaching an extraction point in Escape from Tarkov can become more tense than defeating an opponent, especially with a full backpack.",
  78: "Armour, a flight path or a position at sea asks you to think about combat in different ways in War Thunder. Learn the strengths and weaknesses of your machine across battles involving ground vehicles, aircraft and ships. Spotting an opponent does not automatically give you the advantage; reading distance, angles and movement can change how the encounter unfolds.",
  79: "Even heavy armour cannot make a poor position safe in World of Tanks. Learn your tank's role, look for cover and vision advantages, and adjust your firing line as your team advances. Each encounter has the feel of an armoured chess match, testing when to push forward and when to wait for an opponent to expose a weakness.",
  80: "Dropping onto dangerous planets in the name of Super Earth takes powerful weapons and a squad that can rely on one another. Complete objectives, coordinate support calls and fight towards extraction as the chaos grows in Helldivers 2. With friendly fire part of the equation, even a well-meant rescue can become the kind of comic disaster your group remembers for weeks.",
  81: "Rocket League starts with a simple idea: use a rocket-powered car to put the ball in the opposing goal. Controlling your speed, reading a rebound and taking flight at the right moment become skills you can keep refining. A well-placed pass or last-second save can be as exciting as a spectacular goal, making teamwork immediately rewarding.",
  82: "Your champion in League of Legends shapes the journey from an opening lane duel to the plan for breaking the enemy base. Gather resources, track map objectives and time your abilities through team fights. Turning the advantage of defeating an opponent into towers and objectives is what converts an individual success into progress towards a team victory.",
  83: "Dota 2 offers a deep contest in which the same hero can take on a different role through item choices and teammates. Weigh lane pressure, information around the map and the time needed to grow stronger. A well-prepared team fight can turn the game, but the opportunity often comes from smaller decisions made long before that moment.",
  84: "Wild Rift brings League of Legends champions and lane battles to a pace shaped around touch controls. Gather resources, move across the map and reach the openings your teammates create without wasting time. Playing on mobile does not make it a test of quick fingers alone; knowing when to act together can decide the direction of a match.",
  85: "Your hero's role in Honor of Kings forms part of how a five-player team fights as a whole. While working for an advantage in lane, you must also notice opportunities developing elsewhere on the map. Beyond the spectacular abilities, focusing the right target and supporting a teammate on time are what connect the pieces of its mobile arena battles.",
  86: "In SMITE 2, gods from mythology become fighters you see from behind rather than distant figures on a battlefield. Aim abilities and evade attacks while keeping your team's wider map plan in mind. That close perspective brings a MOBA's objective and progression decisions into the same fight as the immediate movement of an action game.",
  87: "Predecessor places you directly inside its lane battles through a third-person camera. As your hero grows stronger, keep track of your aim, position and whether your team is ready to commit. Breaking the opposing defence takes more than winning fights: knowing when to convert pressure into a map objective is part of the same contest.",
  88: "Deadlock combines hero abilities with gunfights, but winning a duel is only part of what it asks from you. Apply pressure across the map, develop your character and find positions that support your team's advance. Immediate aiming skill and longer-term decisions overlap, so the value of a good fight depends on what you do with the advantage afterwards.",
  89: "Heroes of the Storm brings familiar faces from Blizzard's worlds together on battlegrounds with different objectives. What your team works to secure on one map can give way to a very different plan on the next. Shared experience and talent choices made during the match encourage you to think about personal strength alongside the pace of the whole team.",
  90: "Searching Lumia Island in Eternal Return turns gathered materials into the equipment you need to survive. Plan where to go and when to finish your items while staying ready to meet rival survivors. Crafting and preparation feed into ability-driven combat, making a well-chosen route potentially as important as a powerful attack.",
  91: "Battlerite focuses on short, intense arena encounters that bring you straight into a contest with your opponents. Aim your champion's attacks, preserve escape tools and exploit the openings a teammate creates. In its two- or three-player teams, the difference between a wasted ability and a perfectly timed defence becomes immediately tangible.",
  92: "The lanes, towers and jungle paths of Arena of Valor become the framework for your team's shared plan on a mobile screen. Carry out your chosen hero's role while looking for the right moment to help another lane. Remembering the wider map during quick fights can prevent a promising duel from turning into an enemy ambush.",
  93: "Onmyoji Arena brings the shikigami of the Onmyoji world into five-on-five team battles. Find a character that suits you and learn its abilities while tracking lanes and shared objectives in an arena with a distinctive visual identity. Coordinated attacks and timely support create opportunities beyond simply trying to defeat your own opponent.",
  94: "The part of the map you cannot see can matter as much as the opponent in front of you in Heroes Evolved. Develop your hero while using vision tools and routes between lanes to gather information for your team. Fog of war adds tension to the decision to engage: sometimes an advantage begins with locating the enemy before unleashing your strongest attack.",
  95: "Legend of Ace puts a card system at the centre of hero development, adding a different layer of preparation to five-on-five battles. Think about how your card choices shape your strengths while watching lanes, teammates and chances to attack. Knowing your chosen hero becomes closely linked to deciding the direction in which you want that hero to grow.",
  96: "A colourful course in Fall Guys can stop looking innocent the moment its first spinning obstacle sends everyone tumbling. Weave through the crowd, time your jumps and change plans on the fly to stay in contention. A tiny stumble near the finish can rewrite the whole race, making failure part of the entertainment rather than simply the end of it.",
  97: "The cuddly animals in Party Animals do little to calm its physics-driven clashes with friends. Grabbing an opponent, keeping your balance or completing a team objective can all unravel as the controls turn wonderfully awkward. A plan to win may matter less to the memory of a match than the moment everyone laughs at a move going wrong together.",
  98: "Gang Beasts makes its brawlers feel less like trained fighters and more like unstable puppets desperately hanging on. Trying to throw an opponent over an edge also means watching your own footing and grip. Hazardous locations and clumsy movement turn a serious rivalry between friends into an absurd struggle to remain the last one standing.",
  99: "Getting an order out in Overcooked! 2 depends on everyone following the same plan, not just chopping quickly. Divide jobs, carry plates, cook meals and toss ingredients to friends across moving and unusual kitchens. As the timer runs down, coordination turns into a small triumph, while one misunderstood instruction can become a burnt dinner.",
  100: "Even a simple movement becomes a small physics experiment as your character explores the dreamlike spaces of Human: Fall Flat. Carry objects, cling to ledges and use surrounding mechanisms to find a way past each obstacle. A solution discovered alone can become a completely different approach with friends, leaving the journey to the goal more memorable than the goal itself.",
  101: "Planning your next move around the board in Pummel Party also means remembering that your friends are plotting against you. Use advantages earned in minigames and the items you collect to shift the contest in your favour. Watching yesterday's leader fall behind after an unexpected intervention gives this party's friendly rivalries plenty of material for later conversation.",
  102: "Getting a sofa through a doorway becomes a lively puzzle to solve with friends in Moving Out 2. Carry furniture, clear paths and reorganise jobs in unusual locations as carefully laid plans quickly fall apart. Physics-driven clumsiness turns the stress of moving into a shared scramble that is much more entertaining than an actual day of hauling boxes.",
  103: "Jackbox Party Pack 11 brings out a group's creativity and shared sense of humour through five different party games. Using a phone as a controller, you contribute answers or take part through other forms such as drawings and sound. Much of the fun comes from unexpected responses and the group's own jokes rather than anyone delivering a flawless performance.",
  104: "In Ultimate Chicken Horse, you build more of the course you are trying to finish with every round. A platform can open a route for you while a trap makes life harder for friends, though you still have to cross it yourself. The contest is about jumping well and designing just enough mischief to trouble everyone else without destroying your own chances.",
  105: "One player faces the bomb while the others consult a manual without being able to see it. Keep Talking and Nobody Explodes demands clear descriptions, careful instructions and real listening as the timer runs down. Misdescribing a seemingly simple symbol can raise the tension, while a successful defusal feels like a shared victory in finding the same language.",
  106: "A colourful spaceship has more jobs than one seat can handle, sending you between engines, weapons and shields. Share those stations with your team in Lovers in a Dangerous Spacetime as you navigate danger and rescue friends along the way. Beneath the cheerful appearance is a busy cooperative challenge about knowing who should run where at just the right moment.",
  107: "The instruction that could save your spaceship in Spaceteam often refers to a control on somebody else's screen. Everyone works their own panel while trying to pass commands to the right person, quickly filling the room with competing voices. Rushing without drowning one another out is harder than it sounds, making shared panic part of the fun alongside success.",
  108: "The surface of an alien ocean may seem like a safe beginning in Subnautica, but the real world waits below. Watch your oxygen, study unfamiliar life and turn gathered materials into equipment that lets you venture deeper. The comfort of returning to your underwater base contrasts with the unease of a first descent, keeping the desire to explore alive.",
  109: "Subnautica 2 takes curiosity and survival into a new alien ocean. Explore alone or with friends, gathering resources, crafting equipment and creating a place to live beneath the water. Each new area balances the urge to discover what lies beyond an inviting view against the need to be prepared enough to return from the journey.",
  110: "A Viking journey that begins with a small shelter in Valheim demands greater preparation as new lands open up. Gather resources from forests and shores, develop your base, prepare food and set out to confront powerful enemies. The warmth of a hall built together or a return from a long sea voyage can become as memorable as the toughest battles.",
  111: "After a plane crash in The Forest, building shelter and finding food are only the first steps towards understanding your surroundings. Materials gathered by day help protect you at night, while caves replace the familiar surface with deeper uncertainty. The island's secrets keep calling you beyond your refuge, pulling you between the urge to explore and the desire to stay safe.",
  112: "Surviving the dangerous island of Sons of the Forest takes more preparation than simply finding a weapon. Cut timber, build shelter, search for food and revise your plans as exploration reveals new threats. Quiet moments spent working in the woods contrast with the unease of a sound in the dark, making the creation of a safe place an achievement of its own.",
  113: "Even entering an empty house in Project Zomboid means weighing the need for food against the risk of making noise. Manage injuries, fatigue and daily necessities while deciding how long a seemingly safe neighbourhood can remain home. The fragility of your routine under the zombie threat makes small, carefully prepared survival decisions matter more than grand heroics.",
  114: "The value of a day's scavenging in 7 Days to Die becomes clear when your base comes under attack. Search ruined buildings, craft equipment and construct defences that can withstand an approaching zombie assault. Each preparation cycle gives you a chance to rethink the wall that failed or the escape route that proved badly placed during the last attack.",
  115: "With a tiny body in Grounded, an ordinary backyard becomes a world of towering grass and dangerous insects. Build tools and shelters from surrounding materials while details you would normally overlook shape your route. Reaching a water droplet or crossing an insect's territory is no longer a trivial errand at this scale, but an adventure in its own right.",
  116: "Exploring one planet's horizon in No Man's Sky comes with the knowledge that more worlds wait overhead. Improve your ship and equipment, collect resources, build bases and let curiosity set the course. Encounters with unfamiliar life, pauses in unusual landscapes and journeys to another system make progress feel shaped by your own habits as an explorer.",
  117: "The camp you build with friends in Don't Starve Together survives hunger and darkness only through preparation. Share the work of gathering supplies while adapting to changing conditions, seasons and the differences between your characters. In this strange, illustrated world, making it through another evening often means planning the following day together before trouble arrives.",
  118: "A raft that begins as a few pieces of floating wood grows into a home with materials gathered from the ocean. Meet your needs for food and water, explore islands, craft new tools and follow the clues behind your journey. Land on the horizon offers both the promise of needed supplies and a reason to leave your familiar deck for another discovery.",
  119: "Survival in Green Hell's dense jungle means watching your own body as carefully as the plants around you. Check injuries, balance nutrition and learn to use the environment as you establish a safe shelter. Hidden dangers beneath the beautiful setting reveal how a small, hurried decision can turn into a much longer struggle to stay alive.",
  120: "In The Long Dark, seeing where a snowy road leads matters less if you cannot preserve enough warmth and energy to reach it. Judge the weather, supplies and equipment to decide when to travel and when to seek shelter. The solitude within its quiet landscapes makes a fire or a solid refuge feel like far more than another resource on a checklist.",
  121: "The Pals you meet in Palworld are more than creatures that fight beside you; they also take part in the everyday work of your base. Explore regions, gather companions with different abilities and expand production. As exploration, combat and base management connect, building a useful team becomes about more than measuring its strength in battle.",
  122: "Every tunnel you dig pushes back a little more of the underground darkness in Core Keeper. Mine, craft equipment and build a base while discovering new resources and threats across different cavern regions. The steady rhythm of farming sits beside the uncertainty of exploration, turning each return home into preparation for another journey with what you have found.",
  123: "Searching a seemingly empty town for food in DayZ can become far more uncertain when another player appears. Deal with illness, hunger and environmental threats while deciding whom to approach and which risks to take. A small act of help or a misread movement can redirect a survival story that is shaped by encounters rather than a predetermined script.",
  124: "Your first resources in Rust buy you shelter, but protecting it is a challenge of its own. Expand your base while choosing between cooperation, negotiation and conflict with nearby players. In a world where your possessions can become somebody else's objective, a secure door and a reliable neighbour may feel more valuable than another weapon.",
  125: "Building your first shelter in ARK: Survival Ascended feels very different with prehistoric creatures roaming nearby. Gather resources and improve equipment, taming certain animals to open new possibilities for exploration and transport. The small safe patch you carve out gradually becomes a base from which to prepare for larger creatures and more distant territory.",
  126: "The city you lead in Frostpunk must preserve both warmth and hope in the middle of a frozen world. Assign work, distribute resources and decide which laws to introduce as conditions become harder. Successful management is not simply about growing stockpiles; it also asks you to face the human cost of the choices made to keep everyone alive.",
  127: "The problems of a growing city in Frostpunk 2 reach beyond fuel and food into questions about society's future. Establish districts, organise resource production and seek compromises between groups with competing demands. The struggle against the cold continues, but governing people who want different futures for the same city makes every decision more complicated.",
  128: "A habitat that looks beautiful is not enough in Planet Zoo if it fails to meet its animals' needs. Develop the park by considering species care, staff duties and visitor movement together. The creativity of building detailed spaces meets the responsibility of protecting animal welfare, making every new enclosure more than an exercise in decoration.",
  129: "Treating the unusual illnesses of Two Point Hospital starts with well-placed rooms and a capable team. Organise the flow between diagnosis and treatment, develop staff and tackle queues growing in the corridors. Its comic ailments keep the mood light, but the hospital's budget and daily routine still demand thought before every expansion.",
  130: "An exhibit's story in Two Point Museum begins with the expedition you send to discover it. Bring back new pieces, arrange displays and maintain visitor interest while planning care and security. As the museum grows, its success depends not only on what you exhibit, but also on the journey you create for people exploring the collection.",
  131: "Every corridor and room you design in Prison Architect influences the institution's daily operation. Balance security with prisoners' needs, staff routines and the budget available to you. When a small movement or capacity problem grows, it becomes clear that a good plan consists not merely of walls, but of systems that work together.",
  132: "A few resources gathered by hand become the start of interconnected production lines in Factorio. Arrange belts, machines and power systems while discovering how one bottleneck can affect the entire factory. Watching a new solution work perfectly is deeply satisfying, until your expanding operation presents the next problem you cannot resist solving.",
  133: "In Satisfactory, you walk among the pipes and conveyor belts instead of watching the factory only from above. Explore an alien planet, connect discovered resources to production and plan the placement of machines and transport routes. A view beyond the next hill can invite another expedition while also making you calculate how a new supply line might reach it.",
  134: "As your city develops in Anno 1800, even one product can reveal a chain of interconnected production steps. Organise factories, neighbourhoods and trade routes between islands to balance the demands of growth. Amid the energy of industrialisation, one of the most satisfying moments is seeing a seemingly complicated supply network finally settle into reliable operation.",
  135: "You decide what kind of civilisation your spacefaring society will become in Stellaris. Send science ships into the unknown, establish colonies, build relationships with other powers and defend your place in the galaxy. A new encounter is more than another border on the map; it can make you reconsider your beliefs, strategy and plans for the future.",
  136: "An army's success at the front in Hearts of Iron IV rests on decisions made far behind it in factories and transport networks. Direct industry, choose research and use formations as parts of a wider war plan. As diplomacy, production and logistics connect, every advance on the map reveals the preparation and cost required to support it.",
  137: "Shape a country's fate across a span far longer than one ruler's lifetime in Europa Universalis IV. Build alliances, direct trade and balance the opportunities of expansion against the demands of internal stability. Winning a war can be a powerful beginning, but turning acquired territory into lasting strength requires a much longer view.",
  138: "As El Presidente in Tropico 6, weigh the islanders' expectations, the economy and your political future together. Build roads, jobs and services across an archipelago while trying to retain the support of different groups. Bright scenery and satirical humour keep the tone playful, though balancing the budget against popularity is not always a comfortable task.",
  139: "Keeping a breathable environment is only the beginning for the underground colony in Oxygen Not Included. Build systems around water, power, heat and waste, discovering how a solution in one area can create trouble elsewhere. Your colonists' everyday lives depend on your ability to find a safe path through this increasingly intricate web of needs.",
  140: "Against the Storm asks you to bring new settlements to success under different conditions rather than expand one city forever. Build production chains, balance the needs of different peoples and plan around the options available under the pressure of rain and forest. Each beginning rewards experience while presenting a management puzzle that resists the same automatic solution.",
  141: "Growing a small medieval settlement in Manor Lords means considering fields and labour as carefully as the placement of homes. Prepare for the seasons, organise production and use local resources to meet people's needs. When war arrives, those assigned to defend the settlement are also the people keeping it running, giving military decisions consequences beyond the battlefield.",
  142: "Expanding a Viking clan into new territory in Northgard means repeatedly reassessing food and security. Explore regions, assign workers and prepare before the cold season arrives. Using your clan's strengths matters, but growing faster than your resources can support may turn newly claimed land from an advantage into a burden.",
  143: "Sending units towards an objective is not enough in Company of Heroes 3; you must consider their cover and how they support one another. Combine infantry and vehicles to exploit openings, revising plans quickly when pressure builds. The pace of real-time battle asks you to follow a broad map strategy and the position of a handful of soldiers at the same time.",
  144: "Two portals placed on a wall can make an apparently unreachable exit possible in Portal. Solving its test chambers teaches you to think about the direction and speed of movement rather than distance alone. Strange remarks from your guiding voice gradually strengthen the feeling that something else is hiding behind this clean, orderly facility.",
  145: "Line puzzles scattered across an island in The Witness gradually change how you look at your surroundings. Learn new rules by observing examples and making connections yourself rather than following lengthy explanations. When a shadow or a small feature in the landscape gains meaning, it can feel as though the solution was hidden across the entire island, not just on a panel.",
  146: "Puzzles among the traces of an advanced civilisation in The Talos Principle 2 sit alongside questions about humanity's legacy. Use tools and mechanisms to open routes as discoveries draw you towards the secrets of larger structures. The satisfaction of solving a logical problem becomes part of a wider journey about creation, progress and responsibility.",
  147: "The words on screen in Baba Is You are not instructions but rules you can change. Push one into a different place to redefine what counts as a wall, a goal or even you. A level that seems impossible can adopt an entirely new logic once you form the right sentence, making the solution a matter of changing the rules rather than merely obeying them.",
  148: "The orbs you carry in Cocoon are more than tools: they contain worlds you can enter. Move between them to understand connected mechanisms and use possibilities found in one place to solve problems elsewhere. Beneath its restrained presentation is a puzzle journey that gradually deepens the relationships between layers without losing the pleasure of discovery.",
  149: "Guide a lone boy through a world that refuses to explain itself yet unsettles you through every detail in INSIDE. Hide, run and interact with objects to find ways past the obstacles ahead. Told through movement, light and sound rather than words, the journey keeps feeding your curiosity while resisting an easy explanation of what you see.",
  150: "A child's silent journey through LIMBO's black-and-white world asks you to pay attention to every shape. Solve physics-based puzzles, judge your timing and learn the hazards through observation and trial. Its dark atmosphere is built from sparse detail, making each step feel less like a grand spectacle and more like a cautious advance into the unknown.",
  151: "In Viewfinder, a photograph does more than capture a moment; it can become part of the world in front of you. Position images to create passages, reach inaccessible places and learn to look at familiar shapes from unexpected angles. Stepping into what was once a flat picture makes discovering a solution feel like discovering a new rule of reality.",
  152: "In Superliminal, an object that looks tiny from a distance can become large enough to fill a room. Move through dreamlike corridors, manipulate perspective and reposition objects while learning not to trust your first impression. Finding the way forward becomes a strange journey in which changing your viewpoint can matter more than making your reasoning more complicated.",
  153: "In The Room, a tiny mark on a mysterious box can hint at a mechanism waiting to be unlocked. Turn its components, inspect hidden compartments and use a special lens to uncover details that ordinary sight misses. Each mechanism brings a satisfying breakthrough while the mystery surrounding the object draws you deeper into its carefully concealed layers.",
  154: "In Gorogoa, pictures are not simply scenes to admire but parts of a puzzle that comes alive through their connections. Rearrange panels, look deeper into images and overlap details from different worlds to create new paths. This hand-drawn journey finds its magic in the moment you recognize an unexpected relationship between two seemingly unrelated pictures.",
  155: "In The Case of the Golden Idol, suspicious events appear frozen in time, leaving you to reconstruct what happened. Examine possessions, statements and details within each scene, then use your deductions to identify the people and their actions. As connections emerge between seemingly separate cases, a single correctly placed name can transform your understanding of the whole mystery.",
  156: "In Chants of Sennaar, finding your way among divided peoples begins with understanding their languages. Observe symbols, conversations and everyday behavior, assign meanings in your notebook and use what you learn to open new paths. Finally reading a sentence feels like more than solving a puzzle; it is a small step into another community's understanding of the world.",
  157: "In Resident Evil 2, Raccoon City's dark corridors make you consider your ammunition and escape route before opening another door. Follow Leon and Claire's struggle for survival, search for keys and learn when slipping past danger is wiser than fighting it. A hallway that once felt familiar can become threatening again, making even a return trip a tense decision.",
  158: "In Resident Evil 7: Biohazard, Ethan's search for his missing wife leads into a house whose apparent emptiness hides something terrible. Explore its rooms in first person, manage scarce supplies and look for a way out under the threat of the Baker family. A creaking door or movement down a hallway makes the danger feel uncomfortably close.",
  159: "In Resident Evil Village, Ethan's attempt to save his family takes him from a snow-covered village into imposing, unsettling places. Adapt your weapons and supplies to different threats, follow environmental clues and face the distinct horrors of each new area. Beneath the fairy-tale imagery, danger makes opening an intriguing door both tempting and deeply uncomfortable.",
  160: "In Alan Wake 2, a murder investigation and the story of a writer trapped in darkness begin to intrude upon one another. Follow Saga and Alan, connect clues and use light as part of your defense while reconsidering the meaning of what you see. In a thriller where words can shape reality, wanting to discover the next page comes with the question of whether you can trust it.",
  161: "In The Outlast Trials, surviving the experiments means completing objectives under pressure as well as hiding in the dark. Work alone or with a team, avoid pursuers and search for useful tools while reconsidering routes that seemed safe. Leaving cover to help someone creates a tense choice between protecting yourself and refusing to leave another person behind.",
  162: "In Lethal Company, collecting scrap from abandoned facilities becomes a very different job when an unfamiliar sound breaks the silence. Carry valuables back to the ship with your crew while weighing the time, your load and the risk of entering another room. One greedy final search to meet the quota can turn the trip back into a shared panic that feels much longer than the journey in.",
  163: "In Gran Turismo 7, getting to know a car goes beyond adding it to your garage; it means learning its weight and reactions on the circuit. Try different vehicles, refine their setup and improve your lap times through cleaner cornering. An appreciation for car culture meets the desire to master driving, making a small improvement in technique feel like a victory of its own.",
  164: "In Forza Motorsport, taking a corner better means reading your car's limits rather than simply braking later. Refine your racing line, vehicle setup and positioning among opponents as you work toward more consistent laps on the circuit. Reaching the checkered flag becomes a test of maintaining control across an entire race, not just finding a few seconds of spectacular speed.",
  165: "In Assetto Corsa Competizione, GT racing demands close attention to grip and braking points. Read tire behavior, track conditions and your opponents' lines to build a driving rhythm that is sustainable as well as fast. The satisfaction of getting one corner exactly right becomes something greater when you can maintain that precision throughout the race.",
  166: "In DiRT Rally 2.0, your co-driver's calls often tell you about the next corner before you can see it. Adapt to surface grip, changing gradients and the car's shifting weight as you try to complete each stage cleanly. Knowing that one mistake can affect the kilometers ahead makes restraint just as valuable as the confidence to keep accelerating.",
  167: "In EA Sports WRC, a rally stage is a rhythm you build through changing conditions rather than a simple sequence of corners. Listen to your co-driver, balance the car across different surfaces and decide how much speed to carry when the road narrows. Maintaining your focus over every kilometer makes the finish line a reward for controlled driving as well as outright pace.",
  168: "In The Crew Motorfest, Hawaii's scenery is an invitation to try a new car or take an unexpected detour. Join events built around different motoring cultures, explore between races and switch up your driving style along the way. The highlight of a session can come from an unplanned drive in a favorite vehicle just as easily as from winning a race.",
  169: "In Wreckfest, approaching the first corner means watching the intentions of nearby drivers as closely as the ideal racing line. Feel the damage accumulate as you squeeze past opponents, survive heavy contact and try to keep enough of your car intact to finish. Controlled driving collides with crumpled-metal chaos, where handling an impact can matter as much as outright speed.",
  170: "In Trackmania, a few seconds of track can become a challenge you repeat endlessly in search of a cleaner line. Learn ramps, sharp turns and unusual track sections while chasing your ghost and improving one small detail on each attempt. Quick restarts turn failure into another opportunity to edge closer to your record instead of a long wait before trying again.",
  171: "In GRID Legends, the lights going out begins a fight to find your place in a crowded field. Take different vehicles onto the track, seize openings in close competition and adapt your driving to pressure from other racers. A dramatic story woven around the racing gives you another reason to return, following the rivalries as well as chasing a better result.",
  172: "In Mario Kart 8 Deluxe, a perfectly timed drift can earn a lead, but an item from behind can change the race in an instant. Learn shortcuts across colorful courses and decide when to use your items for attack or protection. With the outcome uncertain until the final stretch, each race with friends can end with a new moment everyone wants to talk about.",
  173: "In Real Racing 3, a small touch can determine how much speed you carry out of a corner. Develop your cars, learn braking points on different circuits and look for the right moment to use a gap between rivals. The search for a cleaner lap brings a focused driving challenge to a mobile session, rewarding a better understanding of a familiar track each time you return.",
  174: "In Need for Speed No Limits, a short street race demands enough focus to spot the right opening in traffic. Upgrade your car, change its appearance and choose when to use nitro as you try to get ahead of your rivals. The personal style built in your garage meets the quick tempo of the races, giving each new challenge another reason to take your car back out.",
  175: "In CSR Racing 2, a race is decided in the critical moments between launch and the final gear change. Tune your car, watch the revs and deliver its power at the right time to reach the line before your opponent. Turning a straight stretch of road into such a precise contest reveals how even a tiny timing error can make a substantial difference.",
  176: "In EA Sports FC 26, a scoring chance can come from patient passing that unsettles a defense rather than a spectacular trick. Shape your squad and game plan, read the spaces on the pitch and choose when to accelerate or retain possession. Seeing your footballing ideas work makes the team's movement leading up to a goal feel as rewarding as the final shot.",
  177: "In NBA 2K26, reaching the basket depends on seeing your teammates away from the ball as well as beating your defender. Create space with screens and passes, follow defensive matchups and find the right rhythm for your shot. When every part of a possession comes together, the basket rewards your understanding of team play as much as your individual execution.",
  178: "In WWE 2K26, stepping into the ring means building toward a dramatic moment as well as landing powerful moves. Counter your opponent's attacks, look for openings to seize control and work toward the chance to deliver a finisher. A last-second escape from a pin or an unexpected reversal can change the atmosphere of the rivalry as much as the outcome of the match.",
  179: "In PGA Tour 2K25, looking at the flag is only the start; you must consider the angle and ground your ball will travel across. Read the wind, distance and slope, choose a club and try to match your swing to the line you planned. Within a seemingly quiet hole, decisions between risk and safety create a personal contest that lasts until the final putt.",
  180: "In TopSpin 2K25, drawing your opponent toward one corner can set up the shot into the space they leave behind. Time your contact, vary the rhythm of the rally and look for the position that lets you turn defense into attack. Winning a long point becomes satisfying not just because of a powerful shot, but because you shaped the exchange several strokes earlier.",
  181: "In UFC 5, one moment of misjudged distance can change the direction of a fight. Choose your strikes on the feet, read your opponent's intentions and work for positional control when the contest moves to the ground. Waiting for the right opening instead of attacking without regard for stamina reveals how patience can be an effective weapon in a fierce encounter.",
  182: "In Madden NFL 26, each formation offers a brief moment to read what the other side is preparing. Weigh passing and rushing options on offense, close gaps on defense and connect every gain on the field to your next decision. As the clock and score increase the pressure, choosing the right play becomes just as important as executing it cleanly.",
  183: "In NHL 26, space opens on the ice in an instant and disappears just as quickly. Move the puck between teammates, change the angle of attack and look for the shot that catches the defense off balance. With heavy contact and rapid changes of direction shaping the match, a few seconds of coordinated play can finally turn sustained pressure into a goal.",
  184: "In MLB The Show 26, the duel between pitcher and batter begins before the ball leaves the hand. Consider pitch type and placement, wait for the right moment to swing and account for the opportunities created by runners on base. Knowing that one well-timed contact can change the game fills its patient moments with anticipation for the next delivery.",
  185: "In Nintendo Switch Sports, a bowling delivery or an exchange at the net becomes a quick contest of movement and timing. Learn the rhythm of different sports, refine direction and power and respond to your opponent's next move. Matches with approachable rules can turn a small rivalry in the same room into a succession of enthusiastic requests for another round.",
  186: "In Mario Strikers: Battle League, the football pitch becomes a lively arena where heavy tackles and unexpected items change the flow of play. Open space with passes, position yourself for a shot and exploit chances to disrupt your opponent's formation. Adapting to the chaos lets each goal become a spectacular team effort rather than the result of a conventional match.",
  187: "In Dream League Soccer, building a club gains meaning through the way your signings work together on the pitch. Improve your squad, invest in facilities and use passing lanes during matches to open up the opposition's defense. Watching the club grow step by step makes a win feel like part of a longer journey rather than simply the result of that day's game.",
  188: "In EA Sports FC Mobile, a new player's value emerges through the role they fill in the team you build. Develop your footballers, adjust your formation and bring decisions about passing, movement and finishing onto the pitch in short mobile sessions. The excitement of adding a card becomes a more personal achievement when you see an attacking idea built around that player work.",
  189: "In Football Manager 26, match-day decisions put the squad and tactics you prepared weeks earlier to the test. Manage the transfer budget, player roles and relationships within the team while finding answers to problems on the pitch. Watching a young player develop or seeing a plan succeed away from home makes the club's story feel shaped by your own work.",
  190: "In Omega Strikers, hitting the moving core matters as much as anticipating where the next rebound will take it. Use your character's abilities to create space, pressure opponents and combine with teammates on a route toward the goal. Attack and defense switch so quickly that a well-timed save can immediately become the beginning of your next scoring chance.",
  191: "In Awesomenauts, jumping through a two-dimensional arena means watching your team's route forward as well as the opponent in front of you. Upgrade your character's abilities, support allied units and look for a chance to break through defensive turrets. Platforming movement meets team strategy, letting a small intervention in the right place open an entire lane of opportunity.",
  192: "In Gigantic: Rampage Edition, the clashes between heroes serve a larger struggle centered on your team's enormous guardian. Pursue objectives across the map, combine abilities with your allies and apply pressure together when an attacking opportunity opens. Winning a duel helps, but real progress comes from connecting seemingly scattered fights to the same shared goal.",
  193: "In Catalyst Black, your weapons and abilities shape the role you take on the battlefield. Balance firepower and movement while pursuing objectives with your team, and look for the most effective moment to transform into a powerful Primal. Using that transformation to complete a coordinated push, rather than only as an escape from trouble, can change the pace of an encounter.",
  194: "In Halo Infinite, a firefight can turn on how you use nearby equipment as much as on the weapon in your hands. Balance movement, positioning and accuracy while exploring open spaces in Master Chief's journey or facing opponents in the arena. A well-timed tool or a carefully chosen approach can turn a familiar encounter into a moment shaped by your own plan.",
  195: "In Destiny 2, the weapons and powers you wield as a Guardian become complementary tools in your team's battles. Follow missions across different worlds, reshape your play style with new equipment and coordinate your role with allies in demanding encounters. Finding a sought-after item becomes especially rewarding when it helps you overcome an obstacle that previously stopped your group.",
  196: "In PlateUp!, opening the restaurant doors quickly reveals whether your kitchen layout actually works. Cook meals, keep orders moving and rearrange equipment between services to prepare for the next day's rush. A single plate left in the wrong place can disrupt everything, so a successful evening depends as much on a shared plan as it does on quick hands.",
  197: "In Super Mario Party Jamboree, a dice roll can send your pursuit of a Star along a very different route from the one you planned. Seize opportunities on the board, test your skills in minigames and adjust your next turn around your friends' decisions. Chance and small tactical choices keep producing reasons not to celebrate too early, even when you seem comfortably ahead.",
  198: "In eFootball, opening a defense means finding the right connection between players rather than constantly pushing the ball forward. Shape your team, control the direction and pace of passes and move into the spaces your opponent leaves at the right moment. A patiently constructed attack finished with one touch highlights the moments when your decisions set the rhythm of the game.",
  199: "In F1 25, setting a fast lap and staying competitive through an entire race demand different kinds of preparation. Refine braking points and your racing line while considering tire use, pit timing and the traffic ahead. When precise driving meets race strategy, a decision made at the right moment can become a meaningful advantage just a few corners later.",
  200: "In Rubber Bandits, grabbing your share of the loot and escaping sounds simple until the other thieves start using everything nearby as a weapon. Collect valuables, stop rivals with objects from the environment and find your way out through physics-driven mayhem. An awkward tumble or a last-second stolen haul can ruin a perfect plan and create an escape story your friends will keep laughing about.",
};

export const englishGames: Game[] = games.map((game) => ({
  ...game,
  story: englishStories[game.id] ?? game.story,
}));